import{_ as s,o as a,c as n}from"./chunks/framework.D1Ss-Xl7.js";const y=JSON.parse(`{"title":"Page 34 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"34","title":"Page 34 | Home","prev":"/page/33/","next":"/page/35/","posts":[{"title":"百度网盘新版API","url":"/posts/2014-07-02-baidu-pan/","date":"2014-07-02 14:09","tags":["baidu"],"html":"<p>突然发现百度网盘又更新 API 了....明明 UI 一点都没有更新.我严重怀疑这个前端工程师是有多寂寞...\\n没事就更新 JS...这已经是我观察发现的第三次更新了...每次都导致我的 aria2c 导出脚本失效...</p>\\n<p>于是我又苦苦寻找新版的 JS 到底是怎么实现下载的,虽说可以直接操纵 DOM 获取选中的文件的 fs_id 信息\\n然后 POST 数据获取 dlink(下载地址),但是这样怎么也不够优雅啊...因为百度自己的 JS 肯定实现了这部分内容\\n于是我便花了更多的时间找 API,但是百度那既压缩又混淆的 JS 代码真是读起来特带劲啊(我绝对不是抖 M)</p>\\n<p>于是说一下百度的新版 API 吧:</p>\\n<h2 id=\\"toast-模块\\" tabindex=\\"-1\\">Toast 模块 <a class=\\"header-anchor\\" href=\\"#toast-模块\\" aria-label=\\"Permalink to &quot;Toast 模块&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>新版 API 把每个功能全部模块化,声明某个模块的方法是使用 require 方法.</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#6F42C1\\"> SetMessage</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">msg</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">type</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  var</span><span style=\\"color:#24292E\\"> Toast </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> require</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'common:widget/toast/toast.js'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  Toast.obtain.</span><span style=\\"color:#6F42C1\\">useToast</span><span style=\\"color:#24292E\\">({</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    toastMode: Toast.obtain[type],</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    msg: msg,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    sticky: </span><span style=\\"color:#005CC5\\">false</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br></div></div><p>于是我便封装了一个函数用来实现消息提示.</p>\\n<h2 id=\\"data-center-模块\\" tabindex=\\"-1\\">data-center 模块 <a class=\\"header-anchor\\" href=\\"#data-center-模块\\" aria-label=\\"Permalink to &quot;data-center 模块&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> File </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> require</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'common:widget/data-center/data-center.js'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">return</span><span style=\\"color:#24292E\\"> File.</span><span style=\\"color:#6F42C1\\">get</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'selectedList'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>data-center 模块可以获取选择的文件的 fs_id,通过传入 fs_id 可以获取 dlink.\\nFile.get(&quot;selectedItemList&quot;)可以获取选择的文件的 DOM 结构.</p>\\n<h2 id=\\"commonservice-模块\\" tabindex=\\"-1\\">commonService 模块 <a class=\\"header-anchor\\" href=\\"#commonservice-模块\\" aria-label=\\"Permalink to &quot;commonService 模块&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> Service </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> require</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'common:widget/commonService/commonService.js'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">Service.</span><span style=\\"color:#6F42C1\\">getDlink</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  JSON</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">stringify</span><span style=\\"color:#24292E\\">(File.</span><span style=\\"color:#6F42C1\\">get</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'selectedList'</span><span style=\\"color:#24292E\\">)),</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  'dlink'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  self.aria2_rpc.</span><span style=\\"color:#6F42C1\\">bind</span><span style=\\"color:#24292E\\">(self)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br></div></div><p>commonService 模块有很多实用的功能,但是我们目前只需要这么一个就足够了,有需要的可以自己研究下.getDlink 接受三个参数.第一个是\\n每个要下载的文件的 fs_id,多个文件是数组的字符串方式传入,第二个是获取 dlink 的类型,总共有三个类型 batsh,dlink,nolimit,第一个类型\\n是把传入的多个文件合并成一个压缩包进行下载,返回一个 dlink,第二个是单独获取每个文件的 dlink,第三个还没有尝试过.第三个参数是回调函数\\n会传入 POST 之后获取的 json 数据.</p>\\n<h2 id=\\"设置-ua\\" tabindex=\\"-1\\">设置 UA <a class=\\"header-anchor\\" href=\\"#设置-ua\\" aria-label=\\"Permalink to &quot;设置 UA&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>因为我现在还没找到怎么获取选择的文件名的列表,所以在 aria2c 的时候无法手动指定文件名.貌似不写 UA 的情况下会被限速.\\n设置 chrome 的 UA 文件名会被 encode,所以 aria2c 的时候设置 UA 为百度云管家的 UA</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#005CC5\\"> UA</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#032F62\\"> 'netdisk;4.4.0.6;PC;PC-Windows;6.2.9200;WindowsBaiduYunGuanJia'</span><span style=\\"color:#24292E\\">;</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"设置-cookie\\" tabindex=\\"-1\\">设置 cookie <a class=\\"header-anchor\\" href=\\"#设置-cookie\\" aria-label=\\"Permalink to &quot;设置 cookie&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>百度云盘升级之后仅仅只有 dlink 还不行,还需要一个 name 为<code>BDUSS</code>的 cookie.\\n但是这个 cookie 被设置为 http only,所以 JS 是无论如何也获取不到的.目前只能采用手动设置的方法.\\n还好这个 cookie 每个用户基本都是唯一的,设置一次永久使用,否则真是麻烦.</p>\\n<p>完整版实现<a href=\\"https://gist.github.com/acgotaku/29d1fbe3dbf777c25254\\" target=\\"_blank\\" rel=\\"noreferrer\\">GitHub</a></p>\\n"},{"title":"Archlinux下声卡的设置与折腾","url":"/posts/2014-06-05-archlinux-sound-setting/","date":"2014-06-05 09:22","tags":["linux"],"html":"<p>最近又有瞎折腾装 Arch....发现显卡驱动的安装和设置都不是问题...\\n声卡却老是出现奇怪的问题,便把最近折腾的经验写下来吧~</p>\\n<h2 id=\\"切换默认声卡\\" tabindex=\\"-1\\">切换默认声卡 <a class=\\"header-anchor\\" href=\\"#切换默认声卡\\" aria-label=\\"Permalink to &quot;切换默认声卡&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>发现最近的新本子基本上声卡设备都不止一个,个人猜测应该是 HDMI 音频输出和\\n本机主板上的音频输出吧.可以使用 <code>aplay -l</code> 命令显示所有声卡设备.\\n我机器的输出是:</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">[acgotaku@Archlinux </span><span style=\\"color:#D73A49\\">~</span><span style=\\"color:#24292E\\">]$ aplay -l</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">****</span><span style=\\"color:#24292E\\"> List of PLAYBACK Hardware Devices </span><span style=\\"color:#D73A49\\">****</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">card</span><span style=\\"color:#032F62\\"> 0:</span><span style=\\"color:#032F62\\"> HDMI</span><span style=\\"color:#24292E\\"> [HDA </span><span style=\\"color:#032F62\\">Intel</span><span style=\\"color:#032F62\\"> HDMI],</span><span style=\\"color:#032F62\\"> device</span><span style=\\"color:#032F62\\"> 3:</span><span style=\\"color:#032F62\\"> HDMI</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\"> [HDMI </span><span style=\\"color:#032F62\\">0]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  Subdevices:</span><span style=\\"color:#032F62\\"> 1/1</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  Subdevice</span><span style=\\"color:#6A737D\\"> #0: subdevice #0</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">card</span><span style=\\"color:#032F62\\"> 1:</span><span style=\\"color:#032F62\\"> PCH</span><span style=\\"color:#24292E\\"> [HDA </span><span style=\\"color:#032F62\\">Intel</span><span style=\\"color:#032F62\\"> PCH],</span><span style=\\"color:#032F62\\"> device</span><span style=\\"color:#032F62\\"> 0:</span><span style=\\"color:#032F62\\"> ALC3220</span><span style=\\"color:#032F62\\"> Analog</span><span style=\\"color:#24292E\\"> [ALC3220 </span><span style=\\"color:#032F62\\">Analog]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  Subdevices:</span><span style=\\"color:#032F62\\"> 1/1</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  Subdevice</span><span style=\\"color:#6A737D\\"> #0: subdevice #0</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br></div></div><p>第一个一般为默认的声卡输出设备,显然 HDMI 输出是不对的,导致声音无法正常播放,我们应该把默认声卡切换为\\n第二个.最简单易用的方法是在用户根目录下新建一个 .asoundrc 文件.输入以下内容:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>defaults.pcm.card 1</span></span>\\n<span class=\\"line\\"><span>defaults.pcm.device 0</span></span>\\n<span class=\\"line\\"><span>defaults.ctl.card 1</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>上面的数据可以从声卡设备输出中找到,这样就切换到 card 1 的 device 0 设备了.不过切换之后可能发现还是没有\\n声音,因为 alsa 默认是静音的需要手动解除才行. 这就需要去官方源安装 <code>alsamixer</code> 工具. <a href=\\"https://www.archlinux.org/packages/?name=alsa-utils\\" target=\\"_blank\\" rel=\\"noreferrer\\">alsa-utils</a>\\n我自己安装的 alsamixer 使用界面是:</p>\\n<p><img src=\\"/assets/alsamixer.png\\" alt=\\"alsamixer\\" loading=\\"lazy\\"></p>\\n<p>默认 Master 竖条下方显示的不是 00 而是 MM,表示是静音的,按下 m 键解除静音.</p>\\n<h2 id=\\"耳机有持续的杂音的解决方案\\" tabindex=\\"-1\\">耳机有持续的杂音的解决方案 <a class=\\"header-anchor\\" href=\\"#耳机有持续的杂音的解决方案\\" aria-label=\\"Permalink to &quot;耳机有持续的杂音的解决方案&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>有些情况下即使安装好 alsa 解除静音了,但仍然发现戴耳机的时候没有任何软件发声的时候会有持续的杂音,但是音乐播放器一旦放音乐的时候杂音又消失了.\\n这个问题的原因是 alsa 默认设置 Mic 声道是静音的,我们只需要解除 Mic 声道的静音并调节至合适的值即可.</p>\\n<h2 id=\\"恢复默认的-alsa-设置\\" tabindex=\\"-1\\">恢复默认的 alsa 设置 <a class=\\"header-anchor\\" href=\\"#恢复默认的-alsa-设置\\" aria-label=\\"Permalink to &quot;恢复默认的 alsa 设置&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>有些时候自己胡乱设置导致 alsa 无法正常工作的时候可以通过使用 <code>alsactl restore</code> 命令使 alsa 恢复到默认的配置一般都能正常工作了.</p>\\n"},{"title":"JavaScript中一个经典的正则例子","url":"/posts/2014-05-08-javascript-regular-expressions/","date":"2014-05-08 09:44","tags":["js","regex"],"html":"<p>学习知识的最好方法就是看例子.(个人观点) 因为书上总是会把概念和公式讲的晦涩难懂,才显得作者高大上.所以我总是喜欢\\n通过例子学习知识.每次写正则的时候总是喜欢查看例子学习如何使用,因为正则实在太耗脑细胞了,记不住,也没必要记住.学会\\n如何使用并在项目中熟练运用就好了,经常使用的话也就自然记住了.</p>\\n<p>JavaScript 语言精粹上面有个非常棒的学习例子,每次写正则的时候都会想起它.所以还是记一下分享给大家也方面我查询啦~</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> parse_url </span><span style=\\"color:#D73A49\\">=</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  /</span><span style=\\"color:#D73A49\\">^</span><span style=\\"color:#032F62\\">(?:(</span><span style=\\"color:#005CC5\\">[A-Za-z]</span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#032F62\\">):)</span><span style=\\"color:#D73A49\\">?</span><span style=\\"color:#032F62\\">(</span><span style=\\"color:#22863A;font-weight:bold\\">\\\\/</span><span style=\\"color:#D73A49\\">{0,3}</span><span style=\\"color:#032F62\\">)(</span><span style=\\"color:#005CC5\\">[0-9.\\\\-A-Za-z]</span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#032F62\\">)(?::(</span><span style=\\"color:#005CC5\\">\\\\d</span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#032F62\\">))</span><span style=\\"color:#D73A49\\">?</span><span style=\\"color:#032F62\\">(?:</span><span style=\\"color:#22863A;font-weight:bold\\">\\\\/</span><span style=\\"color:#032F62\\">(</span><span style=\\"color:#005CC5\\">[</span><span style=\\"color:#D73A49\\">^</span><span style=\\"color:#005CC5\\">?#]</span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#032F62\\">))</span><span style=\\"color:#D73A49\\">?</span><span style=\\"color:#032F62\\">(?:</span><span style=\\"color:#22863A;font-weight:bold\\">\\\\?</span><span style=\\"color:#032F62\\">(</span><span style=\\"color:#005CC5\\">[</span><span style=\\"color:#D73A49\\">^</span><span style=\\"color:#005CC5\\">#]</span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#032F62\\">))</span><span style=\\"color:#D73A49\\">?</span><span style=\\"color:#032F62\\">(?:#(</span><span style=\\"color:#005CC5\\">.</span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#032F62\\">))</span><span style=\\"color:#D73A49\\">?$</span><span style=\\"color:#032F62\\">/</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> url </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'http://www.ora.com:80/goodparts?q#fragment'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> result </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> parse_url.</span><span style=\\"color:#6F42C1\\">exec</span><span style=\\"color:#24292E\\">(url);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> names </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> [</span><span style=\\"color:#032F62\\">'url'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'scheme'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'slash'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'host'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'port'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'path'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'query'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'hash'</span><span style=\\"color:#24292E\\">];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> blanks </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> '     '</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> i;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">for</span><span style=\\"color:#24292E\\"> (i </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">; i </span><span style=\\"color:#D73A49\\">&#x3C;</span><span style=\\"color:#24292E\\"> names.</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">; i </span><span style=\\"color:#D73A49\\">+=</span><span style=\\"color:#005CC5\\"> 1</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(names[i] </span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#032F62\\"> ':'</span><span style=\\"color:#D73A49\\"> +</span><span style=\\"color:#24292E\\"> blanks.</span><span style=\\"color:#6F42C1\\">substring</span><span style=\\"color:#24292E\\">(names[i].</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">), result[i]);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br></div></div><p>让我们分解 parse_url 的各个部分,看看它是如何工作的:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>^</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p><code>^</code>字符表示此字符串的开始.它是一个锚,指引 exec 不要跳过那些不像 URL(non-URL-like)的前缀,只匹配那些从开头就像 URL 一样的字符串:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>(?:([A-Za-z]+):)?</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这个因子匹配一个协议名,但仅当它后面跟随一个:(冒号)的时候才匹配.(?:...)表示一个非捕获型分组(noncapturing group).\\n后缀 ? 表示这个分组是可选的. 问号表示重复 0 次或一次.(...)表示一个捕获型分组(capturing group).一个捕获型分组会复制它\\n所匹配的文本,并把其放到 result 数组里.每个捕获型分组都会被指定一个编号.第一个捕获型分组的编号是 1,所以该分组所匹配的文本副本\\n会出现在 result[1]中.[...]表示一个字符类,A-Za-z 这个字符类包含 26 个大写字母和 26 个小写字母.连字符( - )表示范围从 A 到 Z.\\n后缀 + 表示这个字符类会被匹配一次或者多次.这个组后面跟着字符:,它会按字面进行匹配:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>(\\\\/{0,3})</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>下一个因子是捕获型分组 2./表示该匹配/(斜扛).它是\\\\(反斜杠)来进行转义,这样它就不会被错误地解释为这个正则表达式的结束符.后缀{0,3}表示\\n/ 会被匹配 0 次,或者 1~3 次:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>([0-9.\\\\-A-Za-z]+)</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>下一个因子是捕获型分组 3.它会匹配一个主机名,由一个或多个数字、字母,以及 . 或 - 字符组成. - 会被转义为 \\\\- 以防止与表示范围的连字符想混淆:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>(?::(\\\\d+))?</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>下一个可选的因子匹配端口号,它是由一个前置 : 加上一个或多个数字而组成的序列. \\\\d 表示一个数字字符.一个或多个数字组成的数字串会被捕获型\\n分组 4 捕获:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>(?:\\\\/([^?#]*))?</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>接下来是另一个可选的分组.该分组以一个 / 开始. 之后的字符类[^?#]以一个 ^ 开始, 它表示这个类包含除了?和#之外的所有字符.*表示这个字符类\\n会被匹配 0 次或多次.</p>\\n<p>注意这里的处理是不严谨的.这个类匹配除?和#之外的所有字符,其中包括了行结束符、控制字符,以及其他大量不应在此被匹配的字符.大多数情况下,它会按照\\n我们的预期去做,但某些恶意文本可能会有渗透进来的风险.不严谨的正则表达式是一个常见的安全漏洞发源地.写不严谨的正则表达式比写严谨的正则表达式要容易得多.</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>(?:\\\\?([^#]*))?</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>接下来,还有一个以一个 ? 开始的可选分组.它包含捕获型分组 6,这个分组包含 0 个或多个非#字符.</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>(?:#(.*))?</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>最后一个可选分组是以 # 开始的 .会匹配除行结束符以外的所有字符.</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>$</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>$表示这个字符串的结束.它保证在这个 URL 的尾部没有其他更多内容了.</p>\\n"}]},"relativePath":"page/34/index.md","filePath":"page/[page].md"}`),e={name:"page/34/index.md"};function l(p,o,r,c,t,i){return a(),n("div")}const u=s(e,[["render",l]]);export{y as __pageData,u as default};
